package com.proxy.auth

import java.net.{ServerSocket, Socket}
import java.io.{BufferedReader, InputStreamReader, PrintWriter}
import java.util.concurrent.{ConcurrentHashMap, Executors}
import java.time.Instant
import java.security.{MessageDigest, SecureRandom}
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object ProxyServer {
  val SESSION_TIMEOUT_MS = 300000L
  val HMAC_ALGORITHM = "HmacSHA256"
  val services = new ConcurrentHashMap[String, ServiceEndpoint]()
  val activeSessions = new ConcurrentHashMap[String, SessionInfo]()
  val executor = Executors.newFixedThreadPool(16)

  case class ServiceEndpoint(host: String, port: Int, sharedSecret: Array[Byte])
  case class SessionInfo(token: String, serviceId: String, createdAt: Long, nonce: Long)

  // Load shared secrets from the environment instead of hard-coding them in source.
  private def loadSecret(envVar: String): Array[Byte] = {
    val value = System.getenv(envVar)
    if (value == null || value.isEmpty) {
      throw new IllegalStateException(s"Required secret environment variable '$envVar' is not set")
    }
    value.getBytes("UTF-8")
  }

  def main(args: Array[String]): Unit = {
    services.put("backend-api", ServiceEndpoint("10.0.1.5", 8080, loadSecret("BACKEND_API_SHARED_SECRET")))
    services.put("auth-service", ServiceEndpoint("10.0.1.6", 9090, loadSecret("AUTH_SERVICE_SHARED_SECRET")))
    val server = new ServerSocket(4443)
    while (true) {
      val client = server.accept()
      executor.submit(new RequestHandler(client))
    }
  }

  class NonceGenerator(seed: Long) {
    // Cryptographically secure nonce generation using SecureRandom
    // The seed parameter is mixed into SecureRandom for additional entropy
    private val secureRng = new SecureRandom()
    secureRng.setSeed(seed)

    def nextNonce(): Long = {
      secureRng.nextLong()
    }
  }

  // Singleton nonce generator initialized with current time
  // SecureRandom adds its own entropy beyond the provided seed
  val nonceGen = new NonceGenerator(System.currentTimeMillis())

  def generateAuthToken(serviceId: String, nonce: Long): String = {
    val endpoint = services.get(serviceId)
    if (endpoint == null) return null
    val mac = Mac.getInstance(HMAC_ALGORITHM)
    val keySpec = new SecretKeySpec(endpoint.sharedSecret, HMAC_ALGORITHM)
    mac.init(keySpec)
    val timestamp = Instant.now().getEpochSecond
    val payload = s"$serviceId:$timestamp:$nonce"
    val signature = mac.doFinal(payload.getBytes("UTF-8"))
    val token = bytesToHex(signature)
    activeSessions.put(token, SessionInfo(token, serviceId, System.currentTimeMillis(), nonce))
    token
  }

  def validateIncomingAuth(token: String, serviceId: String, timestamp: Long, nonce: Long): Boolean = {
    val endpoint = services.get(serviceId)
    if (endpoint == null) return false
    val now = Instant.now().getEpochSecond
    if (Math.abs(now - timestamp) > 30) return false
    val mac = Mac.getInstance(HMAC_ALGORITHM)
    val keySpec = new SecretKeySpec(endpoint.sharedSecret, HMAC_ALGORITHM)
    mac.init(keySpec)
    val payload = s"$serviceId:$timestamp:$nonce"
    val expectedSig = bytesToHex(mac.doFinal(payload.getBytes("UTF-8")))
    constantTimeEquals(token, expectedSig)
  }

  def constantTimeEquals(a: String, b: String): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    for (i <- 0 until a.length) {
      result |= a.charAt(i) ^ b.charAt(i)
    }
    result == 0
  }

  def bytesToHex(bytes: Array[Byte]): String = {
    bytes.map("%02x".format(_)).mkString
  }

  class RequestHandler(client: Socket) extends Runnable {
    override def run(): Unit = {
      try {
        val reader = new BufferedReader(new InputStreamReader(client.getInputStream))
        val writer = new PrintWriter(client.getOutputStream, true)
        val requestLine = reader.readLine()
        if (requestLine == null) { client.close(); return }

        val parts = requestLine.split(" ")
        if (parts.length < 2) { writer.println("400 Bad Request"); client.close(); return }

        val command = parts(0)
        val serviceId = parts(1)

        command match {
          case "CONNECT" =>
            val nonce = nonceGen.nextNonce()
            val token = generateAuthToken(serviceId, nonce)
            if (token != null) {
              writer.println(s"200 OK $token $nonce")
              proxyTraffic(client, serviceId, token)
            } else {
              writer.println("404 Service Not Found")
            }
          case "VERIFY" =>
            if (parts.length >= 5) {
              val token = parts(2)
              val timestamp = parts(3).toLong
              val nonce = parts(4).toLong
              if (validateIncomingAuth(token, serviceId, timestamp, nonce)) {
                writer.println("200 Verified")
              } else {
                writer.println("403 Forbidden")
              }
            } else {
              writer.println("400 Bad Request")
            }
          case _ =>
            writer.println("405 Method Not Allowed")
        }
        client.close()
      } catch {
        case e: Exception => try { client.close() } catch { case _: Exception => }
      }
    }

    def proxyTraffic(client: Socket, serviceId: String, token: String): Unit = {
      val endpoint = services.get(serviceId)
      if (endpoint == null) return
      val backend = new Socket(endpoint.host, endpoint.port)
      val backendWriter = new PrintWriter(backend.getOutputStream, true)
      backendWriter.println(s"AUTH $token")
      // Bidirectional proxy would continue here
      backend.close()
    }
  }

  def cleanExpiredSessions(): Unit = {
    val now = System.currentTimeMillis()
    val iter = activeSessions.entrySet().iterator()
    while (iter.hasNext) {
      val entry = iter.next()
      if (now - entry.getValue.createdAt > SESSION_TIMEOUT_MS) {
        iter.remove()
      }
    }
  }
}
